local bench_frames=0
local function bench_exit()
 print(string.format("BENCH time=%.9f frames=%d hz=%.6f",manager.machine.time:as_double(),bench_frames,manager.machine.screens[":screen"].refresh))
 manager.machine:exit()
end
local function experiment()
-- Native Neo keyboard and firmware cursor capture helpers. Neo 3.21 only.
local machine = manager.machine
local memory = machine.devices[":maincpu"].spaces.program
local events = {}
local capture_count, capture_tick = 0, nil
local cpu = machine.devices[":maincpu"]
local saved_cpu, saved_ram, saved_mode
local scratch, code, stack = 0x3f000, 0x3ff00, 0x3fe00
local register_names = {"D0", "D1", "D2", "D3", "D4", "D5", "D6", "D7",
    "A0", "A1", "A2", "A3", "A4", "A5", "A6", "SP", "PC", "SR"}
local function cursor_mode(mode)
    -- Invoke the real firmware SetCursorMode syscall on a temporary test stack.
    -- No framebuffer edits and no changes to the applet binary.
    memory:write_u16(code, 0xa018)
    memory:write_u16(code+2, 0x60fe)
    memory:write_u32(stack, code+2)
    memory:write_u32(stack+4, mode)
    cpu.state.SR.value = 0x2700
    cpu.state.SP.value = stack
    cpu.state.PC.value = code
end
local function returned()
    assert(cpu.state.PC.value == code+2 or cpu.state.PC.value == code+4, string.format("SetCursorMode did not return: PC=%x", cpu.state.PC.value))
end
local function capture()
    capture_count = capture_count + 1
    saved_cpu, saved_ram = {}, {}
    assert((cpu.state.SR.value & 0x2000) ~= 0, "capture requires supervisor context")
    for _, name in ipairs(register_names) do saved_cpu[name] = cpu.state[name].value end
    for i=0,4095 do saved_ram[i] = memory:read_u8(scratch+i) end
    saved_mode = memory:read_u8(0x48be) -- Neo 3.21 cursor mode (test-only address)
    print(string.format("CAPTURE %d %d %d mode=%x", capture_count,
        memory:read_u16(0x5c72), memory:read_u16(0x5c74), saved_mode))
    cursor_mode(0x0c)
    capture_tick = 0
end

local glyphs={[" "]="000000000000000000000000000000000000000000000000",["!"]="000000001000001000001000001000000000000000001000",["\""]="000000010100010100010100000000000000000000000000",["#"]="000000010100010100111110010100111110010100010100",["$"]="000000001000011110101000011100001010111100001000",["%"]="000000110000110010000100001000010000100110000110",["&"]="000000011000100100101000010000101010100100011010",["'"]="000000011000001000010000000000000000000000000000",["("]="000000000100001000010000010000010000001000000100",[")"]="000000010000001000000100000100000100001000010000",["*"]="000000000000001000101010011100101010001000000000",["+"]="000000000000001000001000111110001000001000000000",[","]="000000000000000000000000000000011000001000010000",["-"]="000000000000000000000000111110000000000000000000",["."]="000000000000000000000000000000000000011000011000",["/"]="000000000000000010000100001000010000100000000000",["0"]="000000011100100010100110101010110010100010011100",["1"]="000000001000011000001000001000001000001000011100",["2"]="000000011100100010000010000100001000010000111110",["3"]="000000111110000100001000000100000010100010011100",["4"]="000000000100001100010100100100111110000100000100",["5"]="000000111110100000111100000010000010100010011100",["6"]="000000001100010000100000111100100010100010011100",["7"]="000000111110000010000100001000010000010000010000",["8"]="000000011100100010100010011100100010100010011100",["9"]="000000011100100010100010011110000010000100011000",[":"]="000000000000011000011000000000011000011000000000",[";"]="000000000000011000011000000000011000001000010000",["<"]="000000000100001000010000100000010000001000000100",["="]="000000000000000000111110000000111110000000000000",[">"]="000000010000001000000100000010000100001000010000",["?"]="000000011100100010000010000100001000000000001000",["@"]="000000011100100010000010011010101010101010011100",["A"]="000000011100100010100010100010111110100010100010",["B"]="000000111100100010100010111100100010100010111100",["C"]="000000011100100010100000100000100000100010011100",["D"]="000000111000100100100010100010100010100100111000",["E"]="000000111110100000100000111100100000100000111110",["F"]="000000111110100000100000111100100000100000100000",["G"]="000000011100100010100000101110100010100010011110",["H"]="000000100010100010100010111110100010100010100010",["I"]="000000011100001000001000001000001000001000011100",["J"]="000000001110000100000100000100000100100100011000",["K"]="000000100010100100101000110000101000100100100010",["L"]="000000100000100000100000100000100000100000111110",["M"]="000000100010110110101010101010100010100010100010",["N"]="000000100010100010110010101010100110100010100010",["O"]="000000011100100010100010100010100010100010011100",["P"]="000000111100100010100010111100100000100000100000",["Q"]="000000011100100010100010100010101010100100011010",["R"]="000000111100100010100010111100101000100100100010",["S"]="000000011110100000100000011100000010000010111100",["T"]="000000111110001000001000001000001000001000001000",["U"]="000000100010100010100010100010100010100010011100",["V"]="000000100010100010100010100010100010010100001000",["W"]="000000100010100010100010101010101010101010010100",["X"]="000000100010100010010100001000010100100010100010",["Y"]="000000100010100010100010010100001000001000001000",["Z"]="000000111110000010000100001000010000100000111110",["["]="000000011100010000010000010000010000010000011100",["\\"]="000000000000100000010000001000000100000010000000",["]"]="000000011100000100000100000100000100000100011100",["^"]="000000001000010100100010000000000000000000000000",["_"]="000000000000000000000000000000000000000000111110",["`"]="000000010000001000000100000000000000000000000000",["a"]="000000000000000000011100000010011110100010011110",["b"]="000000100000100000101100110010100010100010111100",["c"]="000000000000000000011100100000100000100010011100",["d"]="000000000010000010011010100110100010100010011110",["e"]="000000000000000000011100100010111110100000011100",["f"]="000000001100010010010000111000010000010000010000",["g"]="000000000000011110100010100010011110000010011100",["h"]="000000100000100000101100110010100010100010100010",["i"]="000000001000000000011000001000001000001000011100",["j"]="000000000100000000001100000100000100100100011000",["k"]="000000100000100000100100101000110000101000100100",["l"]="000000011000001000001000001000001000001000011100",["m"]="000000000000000000110100101010101010100010100010",["n"]="000000000000000000101100110010100010100010100010",["o"]="000000000000000000011100100010100010100010011100",["p"]="000000000000000000111100100010111100100000100000",["q"]="000000000000000000011010100110011110000010000010",["r"]="000000000000000000101100110010100000100000100000",["s"]="000000000000000000011100100000011100000010111100",["t"]="000000010000010000111000010000010000010010001100",["u"]="000000000000000000100010100010100010100110011010",["v"]="000000000000000000100010100010100010010100001000",["w"]="000000000000000000100010100010101010101010010100",["x"]="000000000000000000100010010100001000010100100010",["y"]="000000000000000000100010100010011110000010011100",["z"]="000000000000000000111110000100001000010000111110",["{"]="000000000100001000001000010000001000001000000100",["|"]="000000001000001000001000001000001000001000001000",["}"]="000000010000001000001000000100001000001000010000",["~"]="000000010000101010000100000000000000000000000000"}
local graphics={["blank"]="",["north"]="",["east"]="",["north-moved"]="",["square20"]="",["square20-north"]="",["pen-line"]="",["home-line"]="",["square10"]=""}
local expectations={{graphics="north"},{graphics="blank"},{graphics="square20"},{graphics="square20-north"},{graphics="square20"},{graphics="square20"},{graphics="blank"},{graphics="blank"},{graphics="pen-line"},{graphics="pen-line"},{graphics="home-line"},{graphics="blank"},{graphics="square10"},{graphics="north"},{graphics="east"},{graphics="blank"},{graphics="east"},{graphics="north"},{graphics="north-moved"},{graphics="north-moved"}}
local key_hold=3;local key_step=8;local key_gap=5
local actions={}
local screen=machine.screens[":screen"]
local function named(name)
 for row=0,15 do for _,f in pairs(machine.ioport.ports[":ROW"..row].fields) do
  if f.name:sub(1,#name+2)==name.." [" then return f end
 end end
 error('missing Neo key '..name)
end
local function black(x,y) return (screen:pixel(x,y) & 0xffffff)==0x25302a end
local function cell(x,y,char)
 local bits=glyphs[char];if not bits then return false end
 for dy=0,7 do for dx=0,5 do
  if black(x+dx,y+dy)~=(bits:sub(dy*6+dx+1,dy*6+dx+1)=='1') then return false end
 end end
 return true
end
local function ready()
 for row=0,7 do
  local y=row*8
  if applet=='logo' then
   if (cell(0,y,'?') or cell(0,y,'>')) and cell(6,y,' ') then
    local valid=true
    for yy=y,y+7 do
     for x=12,131 do if black(x,yy)~=(x==12) then valid=false;break end end
     if not valid then break end
    end
    if valid then return true end
   end
  elseif memory:read_u8(0x48be)==0x0f and cell(0,y,'>') and cell(6,y,'>') and cell(12,y,'>') then
   local valid=true
   for yy=y,y+7 do for x=18,263 do
    if x~=23 and x~=24 and black(x,yy) then valid=false;break end
   end;if not valid then break end end
   if valid then return true end
  end
 end
 return false
end
local function matches(spec)
 if spec.graphics then
  local bits=graphics[spec.graphics]
  for y=0,63 do for x=0,131 do
   local index=y*132+x+1
   if black(132+x,y)~=(bits:sub(index,index)=='1') then return false end
  end end
 end
 return ready()
end
local function key(name,modifier,hold)
 actions[#actions+1]={kind='key',name=name,modifier=modifier,hold=hold or key_hold,step=math.max(key_step,(hold or key_hold)+key_gap)}
end
local punctuation={[' ']='Space',['=']='Equals',['-']='Minus',['.']='Period',[',']='Comma',[';']='Semicolon',["'"]='Quote',['[']='Left bracket',[']']='Right bracket',['/']='Slash',['\\']='Backslash',['`']='Grave',['\r']='Enter',['\t']='Tab'}
local shifted={['"']='Quote',[':']='Semicolon',['(']='9',[')']='0',['+']='Equals',['_']='Minus',['*']='8',['<']='Comma',['>']='Period',['!']='1',['@']='2',['%']='5',['{']='Left bracket',['}']='Right bracket'}
local function type_text(text)
 for i=1,#text do
  local ch=text:sub(i,i)
  key(shifted[ch] or punctuation[ch] or ch:upper(),(ch:match('%u') or shifted[ch]) and 'Left Shift' or nil)
  if ch=='\r' then actions[#actions+1]={kind='ready'} end
 end
end
local function wait(frames) end -- Expected display state replaces completion sleeps.
local function checkpoint() actions[#actions+1]={kind='capture'} end
local events={}
local function press(frame,name)
 events[frame]=function() named(name):set_value(1) end
 events[frame+6]=function() named(name):clear_value() end
end
local function boot(name)
 applet=name
 press(150,'Y');press(360,'Enter');press(740,'Applets');press(850,'Down')
 if name=='micropython' then press(910,'Down') end
 press(980,'Enter')
end
local function finish() actions[#actions+1]={kind='finish'} end
local function run()
 local frame,index,started,previous=0,1,nil,nil
 emu.register_frame_done(function() bench_frames=bench_frames+1
  local ok,err=pcall(function()
            if capture_tick then
                capture_tick = capture_tick + 1
                -- Two frames allow the firmware call and LCD redraw to complete (~33 ms).
                if capture_tick == 2 then returned() end
                if capture_tick == 3 or capture_tick == 4 then
                    local path = string.format("checkpoint-%02d-%03d.png", capture_count, capture_tick)
                    local err = machine.screens[":screen"]:snapshot(path)
                    assert(not err, tostring(err))
                end
                if capture_tick == 5 then cursor_mode(saved_mode) end
                if capture_tick == 7 then
                    returned()
                    assert(memory:read_u8(0x48be) == saved_mode, "cursor mode not restored")
                    for i=0,4095 do memory:write_u8(scratch+i, saved_ram[i]) end
                    -- Restore the interrupted guest exactly, after restoring the real cursor.
                    for _, name in ipairs(register_names) do cpu.state[name].value = saved_cpu[name] end
                    capture_tick = nil
                end
                return
            end

   frame=frame+1
   if events[frame] then events[frame]() end
   if frame<1100 then return end
   local sig=screen:pixels();local stable=sig==previous;previous=sig
   local item=actions[index];if not item then return end
   if not started then
    started=frame
    if item.kind=='key' then
     item.key=named(item.name);item.mod=item.modifier and named(item.modifier)
     if item.mod then item.mod:set_value(1) end;item.key:set_value(1)
    end
   end
   local age=frame-started
   local function next_action()
    if item.kind~='key' then print(string.format('ADAPT action=%d kind=%s frames=%d',index,item.kind,age)) end
    index=index+1;started=nil
   end
   if item.kind=='key' then
    if age==item.hold then item.key:clear_value();if item.mod then item.mod:clear_value() end end
    if age>=item.step then next_action() end
   elseif item.kind=='ready' then if stable and ready() then next_action() end
   elseif item.kind=='capture' then
    if stable and matches(expectations[capture_count+1]) then next_action();capture() end
   elseif item.kind=='finish' then print('PASS Neo scenario completed');bench_exit() end
   if age>900 then error('readiness timeout at '..index..' kind='..item.kind) end
  end)
  if not ok then print('FAIL adaptive '..tostring(err));bench_exit() end
 end)
end

